/* xx_dbz_extractor.c - search raw data for DBZ.
 *
 * Scans for:
 *   21 3C 6D 61 6E 20 64 61 74 61 62 61 73 65 20 63 6F 6D 70 72 65 73 73 65 64 3E at +0  ("!<man database compressed>")
 * Offset 0 is always tried as well.
 * Each candidate must be accepted by the dbz reader, which also measures it,
 * and named by the detector, both on a view that starts at the candidate.
 * See xx_format_extractor_engine.h.
 *
 * GENERATED by gen_extractors.py from the detector's prefilters.
 */

#include "../xx_format_extractor_engine.h"
#include "xxfclib/formats/dbz/xx_dbz.h"

static const uint8_t k_anchor0[] = { 0x21, 0x3C, 0x6D, 0x61, 0x6E, 0x20, 0x64, 0x61, 0x74, 0x61, 0x62, 0x61, 0x73, 0x65, 0x20, 0x63, 0x6F, 0x6D, 0x70, 0x72, 0x65, 0x73, 0x73, 0x65, 0x64, 0x3E };

static const xx_format_search_anchor k_anchors[] = {
    { k_anchor0, sizeof(k_anchor0), 0U },
};

static const xx_file_type_t k_types[] = { XX_FILE_TYPE_DBZ };

static Abstractformat *xx_dbz_search_open(xx_io_device *window) {
    xx_dbz *reader = xx_dbz_create(window, 0);
    return reader ? &reader->format : NULL;
}

static void xx_dbz_search_close(Abstractformat *format) {
    /* The format is the first member, so this is the reader itself. */
    xx_dbz_free((xx_dbz *)format);
}

static const xx_format_search_desc k_desc = {
    k_types, sizeof(k_types) / sizeof(k_types[0]),
    k_anchors, sizeof(k_anchors) / sizeof(k_anchors[0]),
    xx_dbz_search_open, xx_dbz_search_close
};

static xx_format_search_state *xx_dbz_create_format_search(
    xx_format_extractor *self, xx_io_device *device, const xx_list_s *options,
    xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_create(&k_desc, device, options, pd);
}

static const xx_format_search_info *xx_dbz_get_current_format_info(
    xx_format_extractor *self, xx_format_search_state *state) {
    (void)self;
    return xx_format_search_current(state);
}

static bool xx_dbz_format_search_find_next(xx_format_extractor *self,
                                          xx_format_search_state *state,
                                          xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_find_next(state, pd);
}

static void xx_dbz_free_format_search(xx_format_extractor *self,
                                     xx_format_search_state *state) {
    (void)self;
    xx_format_search_free(state);
}

xx_format_extractor xx_dbz_extractor = {
    xx_dbz_create_format_search,
    xx_dbz_get_current_format_info,
    xx_dbz_format_search_find_next,
    xx_dbz_free_format_search
};
